styles:
body { margin: 0; }
    a { color: #6b521f; text-decoration: underline; text-decoration-color: rgba(138,109,59,0.35); }
    a:hover { color: #5c4826; }
    ::selection { background: rgba(138,109,59,0.25); }

logic:
class Component extends DCLogic {
  state = {
    zoomIndex: null,
    scale: 1,
    offsetX: 0,
    offsetY: 0,
    dragging: false,
    dragStartX: 0,
    dragStartY: 0,
    dragOffsetStartX: 0,
    dragOffsetStartY: 0
  };

  noteData = [
    {
      key: "1986",
      label: "Cinco Mil Pesos Oro \u00b7 5 de agosto de 1986",
      denomination: "Cinco Mil Pesos Oro",
      date: "5 de agosto de 1986",
      prefix: "0750",
      obverse: "Retrato de Rafael N\u00fa\u00f1ez a la izquierda, con la Ermita del Cerrito. Sobreimpresi\u00f3n roja \u201cSPECIMEN\u201d. Numeraci\u00f3n en ceros (000000000).",
      reverse: "Estatua sedente de Miguel Antonio Caro, con el listado de los Estados Unidos de Colombia (1863\u20131886).",
      condition: "Gema sin circular, con perforaciones de cancelaci\u00f3n características.",
      jpg: "uploads/colombia-banco-de-la-republica-5000-pesos-oro-1986-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-5000-pesos-oro-1986-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-5000-pesos-oro-1986-specimen.webp",
      alt: "Billete especimen de Cinco Mil Pesos Oro de El Banco de la República, Colombia, fechado 5 de agosto de 1986, con el retrato de Rafael Núñez y la estatua de Miguel Antonio Caro en el reverso"
    },
    {
      key: "1987",
      label: "Cinco Mil Pesos Oro \u00b7 5 de agosto de 1987",
      denomination: "Cinco Mil Pesos Oro",
      date: "5 de agosto de 1987",
      prefix: "0454",
      obverse: "Retrato de Rafael N\u00fa\u00f1ez a la izquierda, con la Ermita del Cerrito. Sobreimpresi\u00f3n roja \u201cSPECIMEN\u201d. Numeraci\u00f3n en ceros (000000000).",
      reverse: "Estatua sedente de Miguel Antonio Caro, con el listado de los Estados Unidos de Colombia (1863\u20131886).",
      condition: "Gema sin circular, con perforaciones de cancelaci\u00f3n características.",
      jpg: "uploads/colombia-banco-de-la-republica-5000-pesos-oro-1987-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-5000-pesos-oro-1987-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-5000-pesos-oro-1987-specimen.webp",
      alt: "Billete especimen de Cinco Mil Pesos Oro de El Banco de la República, Colombia, fechado 5 de agosto de 1987, con el retrato de Rafael Núñez y la estatua de Miguel Antonio Caro en el reverso"
    },
    {
      key: "1993",
      label: "Cinco Mil Pesos Oro \u00b7 4 de enero de 1993",
      denomination: "Cinco Mil Pesos Oro",
      date: "4 de enero de 1993",
      prefix: "093",
      obverse: "Retrato de Rafael Núñez a la izquierda, con la Ermita del Cerrito y microimpresiones de la Constitución de 1886. Sobreimpresión roja \u201cMUESTRA SIN VALOR\u201d en diagonal. Numeración en ceros (00000000).",
      reverse: "Estatua sedente de Miguel Antonio Caro, con el listado de los Estados Unidos de Colombia (1863\u20131886) y el escudo de Colombia. Sobreimpresión roja \u201cMUESTRA SIN VALOR\u201d.",
      condition: "Gema sin circular, con perforaciones de cancelación características.",
      jpg: "uploads/colombia-banco-de-la-republica-5000-pesos-oro-1993-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-5000-pesos-oro-1993-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-5000-pesos-oro-1993-specimen-640.webp",
      alt: "Billete especimen de Cinco Mil Pesos Oro de El Banco de la República, Colombia, fechado 4 de enero de 1993, con el retrato de Rafael Núñez y la estatua de Miguel Antonio Caro en el reverso"
    }
  ];

  focusClose = () => {
    const closeBtn = document.querySelector('[data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose);
  };

  openZoomAt = (index) => {
    this.setState({ zoomIndex: index, scale: 1, offsetX: 0, offsetY: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose));
  };

  closeZoom = () => {
    this.setState({ zoomIndex: null });
  };

  stopPropagation = (e) => e.stopPropagation();

  zoomIn = () => {
    this.setState(s => ({ scale: Math.min(4, Math.round((s.scale + 0.5) * 10) / 10) }));
  };

  zoomOut = () => {
    this.setState(s => {
      const next = Math.max(1, Math.round((s.scale - 0.5) * 10) / 10);
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale + delta) * 100) / 100));
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onPointerDown = (e) => {
    if (this.state.scale <= 1) return;
    this.setState({
      dragging: true,
      dragStartX: e.clientX,
      dragStartY: e.clientY,
      dragOffsetStartX: this.state.offsetX,
      dragOffsetStartY: this.state.offsetY
    });
  };

  onPointerMove = (e) => {
    if (!this.state.dragging) return;
    const dx = e.clientX - this.state.dragStartX;
    const dy = e.clientY - this.state.dragStartY;
    this.setState({ offsetX: this.state.dragOffsetStartX + dx, offsetY: this.state.dragOffsetStartY + dy });
  };

  onPointerUp = () => this.setState({ dragging: false });

  onKeyDown = (e) => {
    if (e.key === "Escape" && this.state.zoomIndex !== null) this.closeZoom();
  };

  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = "es";
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
  }

  renderVals() {
    const s = this.state;
    const notes = this.noteData.map((n, i) => Object.assign({}, n, { openZoom: () => this.openZoomAt(i) }));
    const active = s.zoomIndex !== null ? this.noteData[s.zoomIndex] : null;

    return {
      notes,
      zoomIndex: s.zoomIndex !== null,
      closeZoom: this.closeZoom,
      stopPropagation: this.stopPropagation,
      zoomInHandler: this.zoomIn,
      zoomOutHandler: this.zoomOut,
      onWheel: this.onWheel,
      onPointerDown: this.onPointerDown,
      onPointerMove: this.onPointerMove,
      onPointerUp: this.onPointerUp,
      zoomInDisabled: s.scale >= 4,
      zoomOutDisabled: s.scale <= 1,
      zoomPercent: Math.round(s.scale * 100) + "%",
      imgTransform: `translate(${s.offsetX}px, ${s.offsetY}px) scale(${s.scale})`,
      imgCursor: s.scale > 1 ? (s.dragging ? "grabbing" : "grab") : "default",
      activeNoteJpg: active ? active.jpg : "",
      activeNoteWebp: active ? active.webp : ""
    };
  }
}
